local ApiaryKeeper = {}
local PRODUCTS = {
    raw_honey = { name = "Surovi med", hiveCost = 1, flowerCost = 1, time = 2, cost = 16, yield = 30, description = "Surovi med iz čebeljih panjev." },
    beeswax = { name = "Čebelji vosek", hiveCost = 1, flowerCost = 1, time = 3, cost = 28, yield = 40, prestige = 1, description = "Čebelji vosek za sveče in kozmetiko." },
    royal_jelly = { name = "Matični mleček", hiveCost = 1, flowerCost = 2, time = 5, cost = 75, yield = 50, prestige = 3, happiness = 1, description = "Matični mleček za zdravilstvo." },
    propolis = { name = "Propolis", hiveCost = 1, flowerCost = 2, time = 6, cost = 110, yield = 55, prestige = 5, happiness = 2, description = "Propolis z zdravilnimi lastnostmi." },
    silver_comb_honey = { name = "Srebrno satje med", hiveCost = 1, silverCost = 1, flowerCost = 2, time = 9, cost = 260, yield = 70, prestige = 11, happiness = 3, description = "Med iz srebrnih satij za plemiče." },
    royal_grand_apiary = { name = "Kraljevski veliki čebelnjak", hiveCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, flowerCost = 3, time = 14, cost = 1300, yield = 100, prestige = 33, happiness = 8, description = "Veliki kraljevski čebelnjak z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Čebelarska postaja", cost = { gold = 220, wood = 120, stone = 100 }, upkeep = 5, qualityBonus = 5 },
    apiary = { name = "Čebelnjak", cost = { gold = 800, wood = 220, stone = 250, flower = 10 }, upkeep = 20, qualityBonus = 18 },
    honey_house = { name = "Medena hiša", cost = { gold = 2000, wood = 350, stone = 600, silver = 25, wax = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_apiary_atelier = { name = "Kraljevski atelje čebelarstva", cost = { gold = 8200, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
ApiaryKeeper.hiveStock = 22; ApiaryKeeper.flowerStock = 24; ApiaryKeeper.silverStock = 8; ApiaryKeeper.goldStock = 6; ApiaryKeeper.jewelStock = 6
ApiaryKeeper.productStock = {}; ApiaryKeeper.buildings = {}; ApiaryKeeper.maker = nil; ApiaryKeeper.activeMaking = {}; ApiaryKeeper.totalProducts = 0; ApiaryKeeper.dayTimer = 0
function ApiaryKeeper.init() ApiaryKeeper.hiveStock=22; ApiaryKeeper.flowerStock=24; ApiaryKeeper.silverStock=8; ApiaryKeeper.goldStock=6; ApiaryKeeper.jewelStock=6; ApiaryKeeper.productStock={}; ApiaryKeeper.buildings={}; ApiaryKeeper.maker=nil; ApiaryKeeper.activeMaking={}; ApiaryKeeper.totalProducts=0; ApiaryKeeper.dayTimer=0; print("[ApiaryKeeper] Royal Apiary Keeper System initialized (6 products, 4 buildings)") end
function ApiaryKeeper.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ApiaryKeeper.maker={name=n or ("Čebelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čebelar najet: %s (spretnost: %d)",ApiaryKeeper.maker.name,s),"success") end; return true end
function ApiaryKeeper.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ApiaryKeeper.build(id) local ok,e=ApiaryKeeper.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ApiaryKeeper.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ApiaryKeeper.getQualityBonus() local b=0; for _,bd in ipairs(ApiaryKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ApiaryKeeper.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.hiveCost and ApiaryKeeper.hiveStock<(d.hiveCost or 0) then return false,"Premalo panjev" end; if d.flowerCost and ApiaryKeeper.flowerStock<(d.flowerCost or 0) then return false,"Premalo cvetja" end; if d.silverCost and ApiaryKeeper.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ApiaryKeeper.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ApiaryKeeper.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #ApiaryKeeper.buildings==0 then return false,"Potrebna delavnica" end; if not ApiaryKeeper.maker then return false,"Potreben čebelar" end; return true end
function ApiaryKeeper.make(pt,qty) qty=qty or 5; local ok,e=ApiaryKeeper.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.hiveCost then ApiaryKeeper.hiveStock=ApiaryKeeper.hiveStock-d.hiveCost*qty end; if d.flowerCost then ApiaryKeeper.flowerStock=ApiaryKeeper.flowerStock-d.flowerCost*qty end; if d.silverCost then ApiaryKeeper.silverStock=ApiaryKeeper.silverStock-d.silverCost*qty end; if d.goldCost then ApiaryKeeper.goldStock=ApiaryKeeper.goldStock-d.goldCost*qty end; if d.jewelCost then ApiaryKeeper.jewelStock=ApiaryKeeper.jewelStock-d.jewelCost*qty end; local t=d.time; if ApiaryKeeper.maker then t=math.max(1,t-math.floor(ApiaryKeeper.maker.skill/12)) end; table.insert(ApiaryKeeper.activeMaking,{id="apiary_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ApiaryKeeper.completeMaking(m) local q=1.0+(ApiaryKeeper.getQualityBonus()/100); if ApiaryKeeper.maker then q=q+(ApiaryKeeper.maker.skill/180) end; q=math.min(2.0,q); ApiaryKeeper.productStock[m.productType]=(ApiaryKeeper.productStock[m.productType] or 0)+m.quantity; ApiaryKeeper.totalProducts=ApiaryKeeper.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ApiaryKeeper.maker then ApiaryKeeper.maker.itemsMade=ApiaryKeeper.maker.itemsMade+m.quantity; if math.random()<0.20 then ApiaryKeeper.maker.skill=math.min(100,ApiaryKeeper.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čebelji produkt pridelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"apiary.completed",{productName=m.productName,yield=m.yield,happiness=m.happiness}) end end
function ApiaryKeeper.update(dt) if not _G.state then return end; ApiaryKeeper.dayTimer=ApiaryKeeper.dayTimer+dt; if ApiaryKeeper.dayTimer>=30 then ApiaryKeeper.dayTimer=0; for i=#ApiaryKeeper.activeMaking,1,-1 do local m=ApiaryKeeper.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ApiaryKeeper.completeMaking(m); table.remove(ApiaryKeeper.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ApiaryKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ApiaryKeeper.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ApiaryKeeper.getStats() return {hiveStock=ApiaryKeeper.hiveStock,flowerStock=ApiaryKeeper.flowerStock,silverStock=ApiaryKeeper.silverStock,goldStock=ApiaryKeeper.goldStock,jewelStock=ApiaryKeeper.jewelStock,productStock=ApiaryKeeper.productStock,numBuildings=#ApiaryKeeper.buildings,hasMaker=ApiaryKeeper.maker~=nil,makerName=ApiaryKeeper.maker and ApiaryKeeper.maker.name or "—",makerSkill=ApiaryKeeper.maker and ApiaryKeeper.maker.skill or 0,activeMaking=#ApiaryKeeper.activeMaking,totalProducts=ApiaryKeeper.totalProducts} end
return ApiaryKeeper
